function nenEfficiency(nat){
  const i = NEN_CATS.indexOf(nat), out = {};
  NEN_CATS.forEach((c, j) => {
    const d = Math.min(Math.abs(i - j), 6 - Math.abs(i - j));
    out[c] = [100, 80, 60, 40][d];
    if(c === 'Specialization' && nat !== 'Specialization') out[c] = 0; // only born specialists
  });
  return out;
}
function generateNen(S, c, used){
  let h = 0; for(const ch of c.id) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  const rng = makeRng((S.seed ^ h ^ 0x9e3779b9) >>> 0);
  const a = c.a;
  const w = {
    Enhancement: 20 + (a.strength + a.determination - 100) * 0.25,
    Transmutation: 18 + (a.agility + a.courage - 100) * 0.2,
    Emission: 18 + (a.speed + a.courage - 100) * 0.2,
    Conjuration: 16 + (a.intelligence + a.perception - 100) * 0.2,
    Manipulation: 16 + (a.strategy + a.intelligence - 100) * 0.2,
    Specialization: 3 + Math.max(0, a.charisma - 70) * 0.25
  };
  let r = rng() * Object.values(w).reduce((s, x) => s + Math.max(1, x), 0), cat = 'Enhancement';
  for(const k of NEN_CATS){ r -= Math.max(1, w[k]); if(r <= 0){ cat = k; break; } }
  const potential = clamp(Math.round((a.determination + a.courage + a.perception) / 3 + rng.gauss(10, 12)), 1, 100);
  const mastery = clamp(Math.round(potential * 0.35 + rng.gauss(8, 8)), 3, 70);
  const capacity = clamp(Math.round((a.endurance + a.determination) / 2 + rng.gauss(0, 10)), 1, 100);
  const output = clamp(Math.round((a.strength + a.courage + a.combat) / 3 + rng.gauss(0, 10)), 1, 100);
  const control = clamp(Math.round((a.intelligence + a.perception + a.agility) / 3 + rng.gauss(0, 10)), 1, 100);
  const status = mastery < 15 ? 'Partially Awakened' : mastery < 35 ? 'Awakened' : mastery < 55 ? 'Trained' : 'Advanced';
  const eff = nenEfficiency(cat);
  let ability = null;
  for(let t = 0; t < 30 && !ability; t++){
    // form: usually the natural category, sometimes a neighbour (never for Enhancement, which cannot create objects)
    const neigh = NEN_CATS.filter(k => eff[k] === 80);
    const formCat = cat === 'Enhancement' || rng() < 0.7 ? cat : rng.pick(neigh);
    const B = rng.pick(NEN_B.filter(f => f[1] === formCat));
    const A = rng.pick(NEN_A.filter(x => x[1].includes(cat) || x[1].includes(formCat)));
    const fits = x => (x[1].includes(cat) || x[1].includes(formCat)) && !(NEN_CLASH[x[0]] || []).includes(A[0]) && (!NEN_ONLY[x[0]] || NEN_ONLY[x[0]].includes(A[0]));
    const Cs = NEN_C.filter(fits);
    const C = Cs.length && rng() < 0.65 ? rng.pick(Cs) : null;
    const name = [A[0], B[0], C && C[0]].filter(Boolean).join(' ');
    if(A[0] === B[0] || (C && (C[0] === A[0] || C[0] === B[0]))) continue;
    if(used.has(name) && t < 29) continue;
    used.add(name);
    const vows = rng() < 0.6 ? rng.shuffle(NEN_VOWS.slice()).slice(0, rng() < 0.3 ? 2 : 1) : [];
    const vowBonus = vows.reduce((s, v) => s + v[1], 0);
    const secondary = formCat !== cat ? formCat : null;
    const effPenalty = secondary ? (100 - eff[secondary]) * 0.3 : 0;
    const power = clamp(Math.round(25 + output * 0.35 + mastery * 0.3 + vowBonus - effPenalty + rng.gauss(0, 5)), 5, 100);
    const accuracy = clamp(Math.round(30 + control * 0.4 + a.perception * 0.2 + mastery * 0.1 - effPenalty / 2 + rng.gauss(0, 5)), 5, 100);
    const costScore = (B[2].startsWith('Long') ? 2 : B[2].startsWith('Mid') ? 1 : 0) + (C ? 1 : 0) + (C && ['Enduring', 'Iron Will', 'Bracing', 'Rewind', 'Stealing Time'].includes(C[0]) ? 1 : 0) + (/Sustained|hour|day|Until/.test(B[4]) ? 1 : 0) - (vows.length ? 1 : 0);
    const cost = ['Low','Moderate','High','Very high'][clamp(costScore, 0, 3)];
    const art = w => (/^[aeiou]/i.test(w) ? 'an ' : 'a ') + w;
    const a0 = A[0].toLowerCase(), b0 = B[0].toLowerCase();
    const verb = rng.pick({
      Enhancement: [`Reinforces the user's ${b0} with aura that behaves like ${a0}`, `Charges the user's ${b0} with the force of ${a0}`, `Turns every ${b0} strike into a blow of pure ${a0}`],
      Transmutation: B[0] === 'Aura' ? [`Changes the user's aura into ${a0}`, `Gives the user's aura every property of ${a0}`] : [`Changes the user's aura into ${a0} and shapes it as ${art(b0)}`, `Wraps the user in ${a0}-like aura that takes the form of ${art(b0)}`, `Lets the user grow ${art(b0)} of living ${a0}`],
      Emission: [`Launches ${a0}-charged aura away from the body as ${art(b0)}`, `Fires ${a0} from the body in the shape of ${art(b0)}`, `Sets loose ${art(b0)} of ${a0}`],
      Conjuration: [`Materializes ${art(b0)} made of ${a0}`, `Calls up ${art(b0)} of solid ${a0}`, `Conjures a lasting ${b0} of ${a0}`],
      Manipulation: [`Uses ${art(a0)} ${b0} as a medium to take hold of a target`, `Controls whoever carries the user's ${a0} ${b0}`, `Plants ${art(a0)} ${b0} on the target and pulls the strings from afar`],
      Specialization: [`A unique ability built on ${art(a0)} ${b0}`, `Turns ${art(a0)} ${b0} into a rule the target must obey`, `Lets the user strike a deal through ${art(a0)} ${b0}, and collect`, `Rewrites one small part of reality through ${art(a0)} ${b0}`]
    }[formCat]);
    ability = {
      alias: rng() < 0.5 ? `${rng.pick(NEN_ADJ)} ${rng.pick(NEN_NOUN)}` : `${rng.pick(NEN_NOUN)} of the ${rng.pick(NEN_ADJ).replace(/'s$/, '')} ${A[0]}`,
      name, keywords: [A[0], B[0]].concat(C ? [C[0]] : []), primary: cat, secondary,
      description: `${verb}${C ? (formCat === 'Manipulation' || formCat === 'Specialization' ? '; it ' : ' that ') + C[2] : ''}. It is ${A[3]}.`,
      activation: `Activated by ${rng.pick(B[3].split('|'))}.`, range: B[2], duration: B[4], cost,
      cooldown: cost === 'Very high' ? 'Needs a full night of rest before reuse' : cost === 'High' ? 'About 10 minutes of Zetsu to recover' : cost === 'Moderate' ? 'A minute of steady breathing' : 'Can be reused almost immediately',
      power, accuracy,
      effect: C ? C[2].charAt(0).toUpperCase() + C[2].slice(1) + '.' : `Raw ${A[0].toLowerCase()} force with no added effect.`,
      weakness: A[2].charAt(0).toUpperCase() + A[2].slice(1) + '.',
      vows: vows.map(v => ({text: v[0], bonus: v[1]})),
      counterplay: [C ? C[3] : null, A[2], vows[0] ? 'exploiting the vow: ' + vows[0][0].toLowerCase() : null].filter(Boolean).map(x => x.charAt(0).toUpperCase() + x.slice(1)).join('; ') + '.'
    };
  }
  // each person's own shape: the natural category stays at 100, the others lean up to ±10 with the body and mind behind them
  // (its own random stream, so the Hatsu drawn above comes out the same as before)
  const vr = makeRng((h ^ 0x51ED27A3 ^ S.seed) >>> 0), mean = NEN_CATS.filter(k => k !== 'Specialization').reduce((s, k) => s + w[k], 0) / 5, effMine = {};
  NEN_CATS.forEach(k => { const b = eff[k]; if(k === cat || b === 0){ effMine[k] = b; return; }
    const sig = k === 'Specialization' ? 0 : clamp((w[k] - mean) / 6, -1, 1); effMine[k] = clamp(b + clamp(Math.round(sig * 6 + vr.gauss(0, 3)), -10, 10), 20, 95); });
  return { category: cat, potential, mastery, capacity, output, control, status, efficiency: effMine,
    techniques: NEN_TECH.filter(t => mastery >= t[1]).map(t => t[0]), hatsu: ability };
}
function awakenHunters(S, p){
  const used = new Set();
  S.candidates.filter(c => c.status === 'Approved').forEach(c => {
    c.nen = generateNen(S, c, used);
    c.career = hunterCareer(c);
    const n = c.nen;
    c.notes.push({p, text: c.dojoNen && c.dojo ? `After the exam: the Nen ${c.first || c.name} had been learning at ${c.dojo.name} comes into the open: a${/^[AEIOU]/.test(n.category) ? 'n' : ''} ${n.category} user. Hatsu: ${n.hatsu.alias} (${n.hatsu.name})` : `After the exam: awakened Nen as a${/^[AEIOU]/.test(n.category) ? 'n' : ''} ${n.category} user. Hatsu: ${n.hatsu.alias} (${n.hatsu.name})`});
    log(S, p, 'nen', `${c.name} awakens Nen after the exam: ${n.category}, Hatsu "${n.hatsu.alias}" (${n.hatsu.name}) — and sets out as a ${c.career}.`, [c.id]);
    c.notes.push({p, text:`Chose a career as a ${c.career}`});
  });
}

function runToEnd(S){ while(!S.finished) runPhase(S); }

function restartState(S){
  const fresh = generateCandidates(S.edition, S.config.applicants, S.seed, S.returning || []);
  Object.assign(S, {candidates: fresh, phase:0, finished:false, log:[], stats:[], started:false, alliances:[], promises:[]});
  useLineup(S);
  setupFamilies(S);
  setupStories(S);
}

function highlights(S){
  const C = S.candidates; if(!S.finished) return [];
  const maxBy = (arr, f) => arr.reduce((b,c) => (!b || f(c) > f(b)) ? c : b, null);
  const out = [];
  const ap = C.filter(c => c.status === 'Approved');
  const z = C.filter(c => c.scores.zevil !== undefined);
  const fighters = C.filter(c => c.wins > 0);
  const add = (label, c, detail) => c && out.push({label, id:c.id, name:c.name, reg:c.reg, detail});
  const mar = C.filter(c => c.scores.marathon !== undefined);
  add('Fastest in the Marathon', maxBy(mar, c => c.scores.marathon), 'Led the field through the tunnels');
  if(z.length){ const b = maxBy(z, c => c.points); add('Top Badge Hunter', b, `${b.badges.length} badges, ${b.points} pts`); }
  if(fighters.length){ const f = maxBy(fighters, c => c.wins); add('Best Fighter', f, `${f.wins} final-phase wins`); }
  if(ap.length){ const u = ap.reduce((b,c) => total(c) < total(b) ? c : b); add('Most Unexpected Hunter', u, `Lowest attribute total among Hunters (${total(u)})`); }
  const early = C.filter(c => c.status === 'Eliminated' && c.out !== null && c.out <= 5);
  if(early.length){ const s = maxBy(early, total); add('Most Surprising Elimination', s, `Total ${total(s)}, out at ${PHASES[s.out].name}`); }
  const st = maxBy(C.filter(c => c.out === null || c.out >= 9 || c.status === 'Approved'), c => c.a.strategy);
  if(st) add('Best Strategist (Phase 3+)', st, `Strategy ${st.a.strategy}`);
  return out;
}

if(typeof module !== 'undefined') module.exports = {chronicle, persona, buildLineup, useLineup, lineupOf, hunterCareer, PHASE_DEFS, expBonus, selectReturning, returningEligible, finalizeAttempts, generateNen, nenEfficiency, perfScore, generateCandidates, newState, runPhase, runToEnd, restartState, PHASES, highlights, ordinal, total};

